package main

import (
	"context"
	"fmt"
	"time"
)

// processWithContext simulates a long operation that respects context cancellation
func processWithContext(ctx context.Context, steps int) error {
	for i := 1; i <= steps; i++ {
		// TODO: check if ctx is done using select
		// If done, return ctx.Err()
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}

		// Simulate work
		time.Sleep(200 * time.Millisecond)
		fmt.Printf("Completed step %d/%d\n", i, steps)
	}
	return nil
}

func main() {
	// TODO: create a context with 500ms timeout
	ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
	defer cancel()

	err := processWithContext(ctx, 5)
	if err != nil {
		switch err {
		case context.DeadlineExceeded:
			fmt.Println("Operation timed out")
		case context.Canceled:
			fmt.Println("Operation was cancelled")
		default:
			fmt.Println("Error:", err)
		}
	} else {
		fmt.Println("All steps completed!")
	}
}
